let fuse;const options={findAllMatches:!0,ignoreLocation:!0,keys:["title","summary","contents"],threshold:0};document.forms[0].addEventListener("submit",e=>{e.preventDefault(),executeSearch()});function loadSearch(){const e=window.location.pathname.startsWith("/en/")?"/en/index.json":"/index.json";fetch(e).then(e=>e.json()).then(e=>{fuse=new Fuse(e.posts,options)})}function executeSearch(){fuse||loadSearch();const e=fuse.search(document.getElementById("search").value);let t="";for(let n of e)t+=formatItem(n.item);document.getElementById("searchResults").innerHTML=t,document.getElementById("post-count").innerText=e.length}loadSearch()